        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.all_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # Strategy A indicator: SMA on SPY close
        self.sma = self.SMA(self.spy, 50, Resolution.Daily)

        # Strategy B indicator: 14-day RSI on AAPL close
        self.rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilder, Resolution.Daily)

        # Strategy A crossing state
        self.prevSpyClose = None
        self.prevSpySma = None

        # Strategy B red-streak state
        self.prevAaplClose = None
        self.aaplRedStreak = 0

    def OnData(self, slice: Slice):
        # Skip all rule evaluation for the day if any subscribed ticker's bar is missing
        for symbol in self.all_symbols:
            if not slice.Bars.ContainsKey(symbol):
                return

        spyBar = slice.Bars[self.spy]
        aaplBar = slice.Bars[self.aapl]

        # ---------------- Strategy A (SPY) ----------------
        if self.sma.IsReady:
            smaValue = self.sma.Current.Value

            if self.prevSpyClose is not None and self.prevSpySma is not None:
                lotA = self.Portfolio[self.spy].Quantity

                # Sell before buy
                if lotA > 0:
                    if self.prevSpyClose >= self.prevSpySma and spyBar.Close < smaValue:
                        self.Liquidate(self.spy)
                        lotA = 0

                if lotA == 0:
                    if self.prevSpyClose <= self.prevSpySma and spyBar.Close > smaValue:
                        targetValue = 0.40 * self.Portfolio.TotalPortfolioValue
                        shares = math.floor(targetValue / spyBar.Close)
                        if shares > 0:
                            self.MarketOrder(self.spy, shares)

            self.prevSpyClose = spyBar.Close
            self.prevSpySma = smaValue
        else:
            self.prevSpyClose = spyBar.Close
            self.prevSpySma = None

        # ---------------- Strategy B (AAPL) ----------------
        if self.prevAaplClose is not None:
            if aaplBar.Close < self.prevAaplClose:
                self.aaplRedStreak += 1
            else:
                self.aaplRedStreak = 0
        else:
            self.aaplRedStreak = 0

        lotB = self.Portfolio[self.aapl].Quantity

        # Sell before buy
        if lotB > 0:
            if self.rsi.IsReady and self.rsi.Current.Value > 60:
                self.Liquidate(self.aapl)
                lotB = 0

        if lotB == 0:
            if self.aaplRedStreak >= 3:
                availableCash = self.Portfolio.Cash
                if availableCash >= 20000:
                    shares = math.floor(20000 / aaplBar.Close)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)

        self.prevAaplClose = aaplBar.Close

