from AlgorithmImports import *

class DualIndependentSlotAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.allSymbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # SMA period not specified by the strategy text; 50-day is used as a
        # standard trend-following default.
        self.smaPeriod = 50
        self.spySMA = self.SMA(self.spy, self.smaPeriod, Resolution.Daily)
        self.aaplRSI = self.RSI(self.aapl, 14, MovingAverageType.Wilder, Resolution.Daily)

        self.SetWarmUp(max(self.smaPeriod, 14) + 5, Resolution.Daily)

        # Slot 1 - Strategy A (SPY) state
        self.lotA_shares = 0
        self.prevSpyClose = None
        self.prevSpySMA = None

        # Slot 2 - Strategy B (AAPL) state
        self.lotB_shares = 0
        self.prevAaplClose = None
        self.aaplRedStreak = 0

    def OnData(self, data: Slice):
        # Continuously update market-state quantities from each symbol's own data,
        # independent of whether other subscribed tickers have data today.

        # Strategy A state: SPY close / SMA cross tracking
        spyCrossAbove = False
        spyCrossBelow = False
        if data.ContainsKey(self.spy) and data[self.spy] is not None:
            spyClose = data[self.spy].Close
            if self.spySMA.IsReady:
                spySmaVal = self.spySMA.Current.Value
                if self.prevSpyClose is not None and self.prevSpySMA is not None:
                    spyCrossAbove = (self.prevSpyClose <= self.prevSpySMA) and (spyClose > spySmaVal)
                    spyCrossBelow = (self.prevSpyClose >= self.prevSpySMA) and (spyClose < spySmaVal)
                self.prevSpyClose = spyClose
                self.prevSpySMA = spySmaVal

        # Strategy B state: AAPL red-day streak
        if data.ContainsKey(self.aapl) and data[self.aapl] is not None:
            aaplClose = data[self.aapl].Close
            if self.prevAaplClose is not None:
                if aaplClose < self.prevAaplClose:
                    self.aaplRedStreak += 1
                else:
                    self.aaplRedStreak = 0
            self.prevAaplClose = aaplClose

        # Check every subscribed ticker has a bar today; if not, skip all rule evaluation.
        for symbol in self.allSymbols:
            if not data.ContainsKey(symbol) or data[symbol] is None:
                return

        if self.IsWarmingUp:
            return

        spyPrice = data[self.spy].Close
        aaplPrice = data[self.aapl].Close

        # ---- Slot 1: Strategy A (SPY) ----
        if self.spySMA.IsReady and self.prevSpySMA is not None:
            if self.lotA_shares > 0:
                if spyCrossBelow:
                    self.MarketOrder(self.spy, -self.lotA_shares)
                    self.lotA_shares = 0
            else:
                if spyCrossAbove:
                    targetValue = 0.40 * self.Portfolio.TotalPortfolioValue
                    quantity = int(targetValue // spyPrice)
                    if quantity > 0:
                        self.MarketOrder(self.spy, quantity)
                        self.lotA_shares = quantity

        # ---- Slot 2: Strategy B (AAPL) ----
        if self.lotB_shares > 0:
            if self.aaplRSI.IsReady and self.aaplRSI.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.lotB_shares)
                self.lotB_shares = 0
        else:
            if self.aaplRedStreak >= 3:
                if self.Portfolio.Cash >= 20000:
                    quantity = int(20000 // aaplPrice)
                    if quantity > 0:
                        self.MarketOrder(self.aapl, quantity)
                        self.lotB_shares = quantity

from AlgorithmImports import *

class MultiStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for t in tickers:
            self.symbols[t] = self.AddEquity(t, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # SMA period for Strategy A's trend filter (not specified in the spec; using 50 days)
        self.SPY_SMA_PERIOD = 50
        self.spy_sma = self.SMA(self.spy, self.SPY_SMA_PERIOD, Resolution.Daily)

        self.AAPL_RSI_PERIOD = 14
        self.aapl_rsi = self.RSI(self.aapl, self.AAPL_RSI_PERIOD, MovingAverageType.Wilders, Resolution.Daily)

        self.AAPL_BUY_AMOUNT = 20000
        self.AAPL_RED_STREAK_TARGET = 3
        self.RSI_SELL_LEVEL = 60
        self.SPY_INVEST_PCT = 0.40

        self.prev_spy_close = None
        self.prev_spy_sma = None

        self.prev_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, slice: Slice):
        # Skip all rule evaluation if any subscribed ticker's bar is missing today
        for t, sym in self.symbols.items():
            if not slice.Bars.ContainsKey(sym):
                return

        spy_close = slice.Bars[self.spy].Close
        aapl_close = slice.Bars[self.aapl].Close

        # Update AAPL consecutive red-day streak
        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # ---- Slot 1 - Strategy A (SPY, SMA cross) ----
        if self.spy_sma.IsReady and self.prev_spy_close is not None and self.prev_spy_sma is not None:
            spy_sma_value = self.spy_sma.Current.Value
            spy_qty = self.Portfolio[self.spy].Quantity

            cross_below = (self.prev_spy_close >= self.prev_spy_sma) and (spy_close < spy_sma_value)
            cross_above = (self.prev_spy_close <= self.prev_spy_sma) and (spy_close > spy_sma_value)

            if spy_qty > 0:
                # Sell reason only evaluated while lot is non-empty
                if cross_below:
                    self.Liquidate(self.spy)
            elif spy_qty == 0:
                # Buy reason only evaluated while lot is empty
                if cross_above:
                    target_value = self.SPY_INVEST_PCT * self.Portfolio.TotalPortfolioValue
                    shares = int(target_value // spy_close)
                    if shares > 0:
                        self.MarketOrder(self.spy, shares)

        # ---- Slot 2 - Strategy B (AAPL, red streak / RSI) ----
        if self.aapl_rsi.IsReady and self.prev_aapl_close is not None:
            aapl_qty = self.Portfolio[self.aapl].Quantity

            if aapl_qty > 0:
                # Sell reason only evaluated while lot is non-empty
                if self.aapl_rsi.Current.Value > self.RSI_SELL_LEVEL:
                    self.Liquidate(self.aapl)
            elif aapl_qty == 0:
                # Buy reason only evaluated while lot is empty
                if self.aapl_red_streak >= self.AAPL_RED_STREAK_TARGET:
                    cash = self.Portfolio.Cash
                    if cash >= self.AAPL_BUY_AMOUNT:
                        shares = int(self.AAPL_BUY_AMOUNT // aapl_close)
                        if shares > 0:
                            self.MarketOrder(self.aapl, shares)
                    # otherwise: do nothing this bar; reason may fire again later

        # ---- Update previous-day state for next bar's comparisons ----
        self.prev_spy_close = spy_close
        self.prev_spy_sma = self.spy_sma.Current.Value if self.spy_sma.IsReady else None
        self.prev_aapl_close = aapl_close

