        # Strategy B - AAPL (red streak buy, RSI level sell)
        if self.lot_b_shares > 0:
            if self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.lot_b_shares)
                self.lot_b_shares = 0
        else:
            if self.aapl_red_streak >= 3:
