        for s in self.all_symbols:
            if not data.Bars.ContainsKey(s):
                return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        # --- Compute market-state quantities ---

        cross_above = False
        cross_below = False
        if self.sma.IsReady and self.prev_spy_sma is not None:
            sma_now = self.sma.Current.Value
            if self.prev_spy_close <= self.prev_spy_sma and spy_close > sma_now:
                cross_above = True
            if self.prev_spy_close >= self.prev_spy_sma and spy_close < sma_now:
                cross_below = True

        if self.aapl_prev_close is not None:
            if aapl_close < self.aapl_prev_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
        else:
            self.aapl_red_streak = 0

