        spy_qty = self.Portfolio[self.spy].Quantity
        if spy_qty > 0:
            if cross_below:
                self.Liquidate(self.spy)
        else:
            if self.sma.IsReady and cross_above:
                target_value = 0.4 * self.Portfolio.TotalPortfolioValue
                qty = int(target_value // spy_close)
                if qty > 0:
                    self.MarketOrder(self.spy, qty)

        # --- Slot 2: Strategy B (AAPL) ---
        aapl_qty = self.Portfolio[self.aapl].Quantity
        if aapl_qty > 0:
