    MA_PERIOD = 50
    RSI_PERIOD = 14
    RSI_SELL_LEVEL = 60
    RED_STREAK_REQUIRED = 3
    AAPL_BUY_AMOUNT = 20000.0
    SPY_INVEST_PCT = 0.40

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.all_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, self.MA_PERIOD, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, self.RSI_PERIOD, MovingAverageType.Wilders, Resolution.Daily)

        self.SetWarmUp(max(self.MA_PERIOD, self.RSI_PERIOD) + 1, Resolution.Daily)

        # Continuous per-symbol market state, updated whenever that symbol has a bar,
        # independent of whether other subscribed tickers have data that day.
        self.prev_spy_close = None
        self.prev_spy_sma = None
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

        # Private per-slot lots
        self.spy_shares = 0
        self.aapl_shares = 0

    def OnData(self, data: Slice):
        spy_bar = data.Bars[self.spy] if data.Bars.ContainsKey(self.spy) else None
        aapl_bar = data.Bars[self.aapl] if data.Bars.ContainsKey(self.aapl) else None

        spy_cross_above = False
        spy_cross_below = False

        if spy_bar is not None and self.spy_sma.IsReady:
            spy_close_today = spy_bar.Close
            spy_sma_today = self.spy_sma.Current.Value
            if self.prev_spy_close is not None and self.prev_spy_sma is not None:
                spy_cross_above = (self.prev_spy_close <= self.prev_spy_sma) and (spy_close_today > spy_sma_today)
                spy_cross_below = (self.prev_spy_close >= self.prev_spy_sma) and (spy_close_today < spy_sma_today)
            self.prev_spy_close = spy_close_today
            self.prev_spy_sma = spy_sma_today

        if aapl_bar is not None:
            aapl_close_today = aapl_bar.Close
            if self.prev_aapl_close is not None:
                if aapl_close_today < self.prev_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.prev_aapl_close = aapl_close_today

        if self.IsWarmingUp:
            return

        for symbol in self.all_symbols:
            if not data.Bars.ContainsKey(symbol):
                return

        if not (self.spy_sma.IsReady and self.aapl_rsi.IsReady):
            return

        # ---------------- Slot 1: Strategy A (SPY) ----------------
        if self.spy_shares > 0:
            if spy_cross_below:
                self.MarketOrder(self.spy, -self.spy_shares)
        else:
            if spy_cross_above:
                target_value = self.Portfolio.TotalPortfolioValue * self.SPY_INVEST_PCT
                price = data.Bars[self.spy].Close
                quantity = int(target_value // price)
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)

        # ---------------- Slot 2: Strategy B (AAPL) ----------------
        if self.aapl_shares > 0:
            if self.aapl_rsi.Current.Value > self.RSI_SELL_LEVEL:
                self.MarketOrder(self.aapl, -self.aapl_shares)
        else:
            if self.aapl_red_streak >= self.RED_STREAK_REQUIRED:
                available_cash = self.Portfolio.Cash
                if available_cash >= self.AAPL_BUY_AMOUNT:
                    price = data.Bars[self.aapl].Close
                    quantity = int(self.AAPL_BUY_AMOUNT // price)
                    if quantity > 0:
                        self.MarketOrder(self.aapl, quantity)

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if orderEvent.Status != OrderStatus.Filled and orderEvent.Status != OrderStatus.PartiallyFilled:
            return
        if orderEvent.Symbol == self.spy:
            self.spy_shares += int(orderEvent.FillQuantity)
        elif orderEvent.Symbol == self.aapl:
            self.aapl_shares += int(orderEvent.FillQuantity)

