        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.all_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # Moving average period not specified by the spec; using a standard 50-day SMA.
        self.spy_sma = self.SMA(self.spy, 50, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.spy_prev_close = None
        self.spy_prev_sma = None
        self.aapl_prev_close = None
        self.aapl_red_streak = 0

        # Private per-strategy lot sizes
        self.a_shares = 0
        self.b_shares = 0

    def OnOrderEvent(self, orderEvent):
        if orderEvent.Status not in (OrderStatus.Filled, OrderStatus.PartiallyFilled):
            return
        if orderEvent.Symbol == self.spy:
            self.a_shares += orderEvent.FillQuantity
        elif orderEvent.Symbol == self.aapl:
            self.b_shares += orderEvent.FillQuantity

    def OnData(self, data: Slice):
        # Skip the entire day if any subscribed ticker's bar is missing.
        for sym in self.all_symbols:
            if not data.Bars.ContainsKey(sym):
                return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        sma_ready = self.spy_sma.IsReady
        rsi_ready = self.aapl_rsi.IsReady

        spy_sma_value = self.spy_sma.Current.Value if sma_ready else None
        aapl_rsi_value = self.aapl_rsi.Current.Value if rsi_ready else None

        cross_above = False
        cross_below = False
        if sma_ready and self.spy_prev_sma is not None and self.spy_prev_close is not None:
            cross_above = (self.spy_prev_close <= self.spy_prev_sma) and (spy_close > spy_sma_value)
            cross_below = (self.spy_prev_close >= self.spy_prev_sma) and (spy_close < spy_sma_value)

        if self.aapl_prev_close is not None:
            if aapl_close < self.aapl_prev_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # ---- Strategy A (SPY): sell before buy ----
        if self.a_shares > 0 and cross_below:
            self.MarketOrder(self.spy, -self.a_shares)
        elif self.a_shares == 0 and cross_above:
            portfolio_value = self.Portfolio.TotalPortfolioValue
            target_value = 0.40 * portfolio_value
            qty = int(target_value // spy_close)
            if qty > 0:
                self.MarketOrder(self.spy, qty)

        # ---- Strategy B (AAPL): sell before buy ----
        if self.b_shares > 0:
            if rsi_ready and aapl_rsi_value > 60:
                self.MarketOrder(self.aapl, -self.b_shares)
        else:
            if self.aapl_red_streak >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    qty = int(20000 // aapl_close)
                    if qty > 0:
                        self.MarketOrder(self.aapl, qty)

        self.spy_prev_close = spy_close
        self.spy_prev_sma = spy_sma_value
        self.aapl_prev_close = aapl_close

