    def OnData(self, data: Slice):
        # Skip all rule evaluation for the day if any subscribed ticker's bar is missing.
        for symbol in self.symbols.values():
            if not data.ContainsKey(symbol) or data[symbol] is None:
                return

        spy_close = data[self.spy].Close
        aapl_close = data[self.aapl].Close

        # Update AAPL red-day streak (continuously computed market-state quantity).
        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # Determine SPY moving-average crosses.
        spy_cross_up = False
        spy_cross_down = False
        if self.spy_sma.IsReady and self.prev_spy_close is not None and self.prev_spy_sma is not None:
            spy_sma_val = self.spy_sma.Current.Value
            if self.prev_spy_close <= self.prev_spy_sma and spy_close > spy_sma_val:
                spy_cross_up = True
            if self.prev_spy_close >= self.prev_spy_sma and spy_close < spy_sma_val:
                spy_cross_down = True

        spy_lot = self.Portfolio[self.spy].Quantity
        aapl_lot = self.Portfolio[self.aapl].Quantity

        # ---- SELLS (evaluated before buys) ----

        # Strategy A sell: SPY close crosses below its moving average -> liquidate lot.
        if spy_lot > 0 and spy_cross_down:
            self.Liquidate(self.spy)

        # Strategy B sell: AAPL 14-day RSI closes above 60 -> liquidate lot.
        if aapl_lot > 0 and self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
            self.Liquidate(self.aapl)

        # ---- BUYS ----

        # Strategy A buy: SPY close crosses above its moving average -> invest 40% of portfolio.
        if spy_lot == 0 and self.spy_sma.IsReady and spy_cross_up:
            self.SetHoldings(self.spy, 0.4)

        # Strategy B buy: AAPL red for 3+ consecutive days -> buy $20,000 of AAPL if cash available.
        if aapl_lot == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                qty = math.floor(20000 / aapl_close)
                if qty > 0:
                    self.MarketOrder(self.aapl, qty)

        # ---- Update "yesterday" references for next bar's cross detection ----
        self.prev_spy_close = spy_close
        if self.spy_sma.IsReady:
            self.prev_spy_sma = self.spy_sma.Current.Value
        self.prev_aapl_close = aapl_close

