        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # Indicators
        self.sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.rsi = self.RSI(self.aapl, 14, Resolution.Daily, MovingAverageType.Wilder)

        # Strategy A (SPY) state
        self.strategy_a_shares = 0
        self.prev_spy_close = None
        self.prev_spy_sma = None

        # Strategy B (AAPL) state
        self.strategy_b_shares = 0
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, slice: Slice):
        # Skip all rule evaluation if any subscribed ticker's bar is missing today
        for symbol in self.symbols:
            if not slice.Bars.ContainsKey(symbol):
                return

        spy_close = slice.Bars[self.spy].Close
        aapl_close = slice.Bars[self.aapl].Close

        # ---- Update market-state quantities (continuously) ----
        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # ---- Slot 1: Strategy A (SPY) ----
        if self.sma.IsReady:
            spy_sma = self.sma.Current.Value

            if self.strategy_a_shares > 0:
                # Sell reason: SPY close crosses below its 100-day SMA
                if self.prev_spy_close is not None and self.prev_spy_sma is not None:
                    crossed_below = (self.prev_spy_close >= self.prev_spy_sma) and (spy_close < spy_sma)
                    if crossed_below:
                        self.MarketOrder(self.spy, -self.strategy_a_shares)
                        self.strategy_a_shares = 0
            else:
                # Buy reason: SPY close crosses above its 100-day SMA
                if self.prev_spy_close is not None and self.prev_spy_sma is not None:
                    crossed_above = (self.prev_spy_close <= self.prev_spy_sma) and (spy_close > spy_sma)
                    if crossed_above:
                        target_value = 0.4 * self.Portfolio.TotalPortfolioValue
                        shares = int(target_value // spy_close)
                        if shares > 0:
                            self.MarketOrder(self.spy, shares)
                            self.strategy_a_shares += shares

            self.prev_spy_close = spy_close
            self.prev_spy_sma = spy_sma

        # ---- Slot 2: Strategy B (AAPL) ----
        if self.rsi.IsReady:
            if self.strategy_b_shares > 0:
                # Sell reason: AAPL 14-day RSI closes above 60
                if self.rsi.Current.Value > 60:
                    self.MarketOrder(self.aapl, -self.strategy_b_shares)
                    self.strategy_b_shares = 0
            else:
                # Buy reason: AAPL has been red for 3 consecutive days
                if self.aapl_red_streak >= 3:
                    cost = 20000.0
                    if self.Portfolio.Cash >= cost:
                        shares = int(cost // aapl_close)
                        if shares > 0:
                            self.MarketOrder(self.aapl, shares)
                            self.strategy_b_shares += shares
                    # otherwise do nothing this bar; reason may fire again later

        self.prev_aapl_close = aapl_close

