        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.tracked_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # Strategy A indicator: SPY 100-day SMA
        self.sma100 = self.SMA(self.spy, 100, Resolution.Daily)

        # Strategy B indicator: AAPL 14-day RSI (Wilder)
        self.rsi14 = self.RSI(self.aapl, 14, MovingAverageType.Wilder, Resolution.Daily)

        # Strategy A cross-detection state
        self.prev_spy_close = None
        self.prev_spy_sma = None

        # Strategy A lot
        self.lotA_shares = 0

        # Strategy B red-streak state
        self.aapl_prev_close = None
        self.aapl_red_streak = 0

        # Strategy B lot
        self.lotB_shares = 0

    def OnData(self, data):
        # If today's bar is missing for ANY subscribed ticker, skip ALL rule evaluation for the day.
        for s in self.tracked_symbols:
            if not data.Bars.ContainsKey(s):
                return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        self._evaluate_strategy_a(spy_close)
        self._evaluate_strategy_b(aapl_close)

    def _evaluate_strategy_a(self, spy_close):
        if not self.sma100.IsReady:
            return

        sma_val = self.sma100.Current.Value

        if self.prev_spy_close is not None and self.prev_spy_sma is not None:
            crossed_above = (self.prev_spy_close <= self.prev_spy_sma) and (spy_close > sma_val)
            crossed_below = (self.prev_spy_close >= self.prev_spy_sma) and (spy_close < sma_val)

            # Sell before buy
            if self.lotA_shares > 0:
                if crossed_below:
                    self.MarketOrder(self.spy, -self.lotA_shares)
                    self.lotA_shares = 0
            else:
                if crossed_above:
                    target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                    shares = int(target_value / spy_close)
                    if shares > 0:
                        self.MarketOrder(self.spy, shares)
                        self.lotA_shares += shares

        self.prev_spy_close = spy_close
        self.prev_spy_sma = sma_val

    def _evaluate_strategy_b(self, aapl_close):
        # Update red-day streak (market-state quantity, computed continuously from data)
        if self.aapl_prev_close is not None:
            if aapl_close < self.aapl_prev_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # Sell before buy
        if self.lotB_shares > 0:
            if self.rsi14.IsReady:
                rsi_val = self.rsi14.Current.Value
                if rsi_val > 60:
                    self.MarketOrder(self.aapl, -self.lotB_shares)
                    self.lotB_shares = 0
        else:
            if self.aapl_prev_close is not None and self.aapl_red_streak >= 3:
                cash_available = self.Portfolio.Cash
                if cash_available >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)
                        self.lotB_shares += shares

        self.aapl_prev_close = aapl_close
